create or replace function public.build_dispute_evidence_bundle(p_dispute_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare d public.disputes%rowtype; bundle jsonb; begin select * into d from public.disputes where id=p_dispute_id and user_id=auth.uid(); if not found then raise exception 'dispute_not_found'; end if; select jsonb_build_object('dispute',to_jsonb(d),'evidence',coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at) from public.dispute_evidence e where e.dispute_id=d.id and e.user_id=d.user_id),'[]'::jsonb),'generated_at',now()) into bundle; return bundle; end $$;
revoke all on function public.build_dispute_evidence_bundle(uuid) from public,anon;
grant execute on function public.build_dispute_evidence_bundle(uuid) to authenticated;